import math

def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve_pa_equation(max_a):
    solutions = []
    for a in range(1, max_a + 1):
        R = 12 * a + 1

        # Check if R is a perfect a-th power, R = p^a
        # We estimate p = R^(1/a)
        try:
            # Use floating point root finding, then check surrounding integers
            # Since p must be an integer, we check floor and ceil of the root.
            p_float = R**(1/a)
            p_low = int(math.floor(p_float))
            p_high = int(math.ceil(p_float))

            found_p = None
            for p_candidate in [p_low, p_high]:
                if p_candidate >= 2:
                    # Check if it's a perfect a-th power
                    if p_candidate**a == R:
                        if is_prime(p_candidate):
                            found_p = p_candidate
                            break

            if found_p is not None:
                solutions.append((found_p, a))

        except OverflowError:
            # R might be too large, though unlikely up to a=30
            pass

    return solutions

# Extend search up to a=30
solutions_30 = solve_pa_equation(30)
print("Solutions found for a <= 30:")
for p, a in solutions_30:
