import math

def tau_n_to_the_12(n):
    """
    Calculates tau(n^12).
    If n = p1^a1 * p2^a2 * ..., then tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...
    """
    if n == 1:
        # tau(1^12) = tau(1) = 1.
        return 1

    factors = {}
    d = 2
    temp_n = n
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    # Calculate tau(n^12) using the exponents 'a'
    tau_n_12 = 1
    for prime, exponent in factors.items():
        a = exponent
        tau_n_12 *= (12 * a + 1)

    return tau_n_12

candidates = [13, 25, 325]
results = {}

print("--- Verification Results ---")
for n in candidates:
    calculated_tau = tau_n_to_the_12(n)
    is_solution = (n == calculated_tau)
    results[n] = {
        "n": n,
        "tau(n^12)": calculated_tau,
        "check": is_solution
    }
    print(f"For n={n}: Calculated tau(n^12) = {calculated_tau}. Does it equal n? {is_solution}")

print("\n--- Structured Summary ---")
for n, res in results.items():
    print(f"n={res['n']}: LHS={res['n']}, RHS={res['tau(n^12)']}. Match: {res['check']}")

